def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Return True if any two elements in ``numbers`` differ by less than ``threshold``."""
    if len(numbers) < 2:
        return False
    # Sorting allows us to only compare adjacent pairs
    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if abs(sorted_nums[i+1] - sorted_nums[i]) < threshold:
            return True
    return False

