def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Parameters:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Ensure we only consider the first n+1 coefficients
    coeffs = coeffs[: n + 1]
    terms = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign_str = '-' if coeff < 0 else ''
        else:
            sign_str = '-' if coeff < 0 else '+'

        abs_coef = abs(coeff)

        # Build coefficient part
        if deg == 0:
            coef_part = str(abs_coef)
        else:
            coef_part = '' if abs_coef == 1 else str(abs_coef)

        # Build variable part
        if deg > 1:
            var_part = f'x^{deg}'
        elif deg == 1:
            var_part = 'x'
        else:
            var_part = ''

        terms.append(f'{sign_str}{coef_part}{var_part}')

    if not terms:
        return '0'
    return ''.join(terms)

